import stylistic from "@stylistic/eslint-plugin";

//#region helpers/getStylisticLegacyConfig.ts
const getStylisticLegacyConfig = (language) => {
	const legacyConfig = stylistic.configs["disable-legacy"];
	const REACT = "react/";
	const TYPESCRIPT = "@typescript-eslint/";
	const rules = Object.entries(legacyConfig.rules ?? {}).reduce((acc, [key, value]) => {
		if (language === "javascript") {
			const condition = !key.startsWith(REACT) && !key.startsWith(TYPESCRIPT);
			return {
				...acc,
				...condition ? { [key]: value } : null
			};
		}
		if (language === "typescript") {
			const condition = key.startsWith(TYPESCRIPT);
			return {
				...acc,
				...condition ? { [key]: value } : null
			};
		}
		if (language === "react") {
			const condition = key.startsWith(REACT);
			return {
				...acc,
				...condition ? { [key]: value } : null
			};
		}
		return null;
	}, {});
	return rules ? {
		...legacyConfig,
		rules
	} : legacyConfig;
};

//#endregion
export { getStylisticLegacyConfig };